from flask import Flask, jsonify, request

app = Flask(__name__)

tasks = {
    'todo': [],
    'in_progress': [],
    'done': []
}

task_id_counter = 1

@app.route('/tasks', methods=['GET'])
def get_tasks():
    return jsonify(tasks)

@app.route('/tasks', methods=['POST'])
def add_task():
    global task_id_counter
    data = request.json
    column = data['column']
    task = data['task']
    task_id = task_id_counter
    task_id_counter += 1
    tasks[column].append({'id': task_id, 'task': task})
    return jsonify({'message': 'Task added successfully', 'id': task_id, 'task': task}), 201

@app.route('/tasks', methods=['PUT'])
def move_task():
    data = request.json
    from_column = data['from_column']
    to_column = data['to_column']
    task_id = data['id']
    task = data['task']
    for i, t in enumerate(tasks[from_column]):
        if t['id'] == task_id and t['task'] == task:
            tasks[from_column].pop(i)
            tasks[to_column].append(t)
            return jsonify({'message': 'Task moved successfully'}), 200
    return jsonify({'message': 'Task not found'}), 404

@app.route('/tasks', methods=['DELETE'])
def delete_task():
    data = request.json
    column = data['column']
    task_id = data['id']
    task = data['task']
    for i, t in enumerate(tasks[column]):
        if t['id'] == task_id and t['task'] == task:
            tasks[column].pop(i)
            return jsonify({'message': 'Task deleted successfully'}), 200
    return jsonify({'message': 'Task not found'}), 404

if __name__ == '__main__':
    app.run(debug=True)
